from __future__ import annotations
from typing import List

def thue_morse_via_dfao(n: int) -> int:
    """f(n) = output of the 2-state Thue-Morse DFAO on the binary digits of n.
    State = parity of #(1-bits); a '1' flips it; out(state)=state."""
    state = 0
    bits: List[int] = [int(b) for b in bin(n)[2:]] if n > 0 else []
    for b in bits:
        state ^= b
    return state

def range_finite_demo(upto: int = 10_000) -> None:
    """Empirically witness Theorem 13 (range_finite): the 2-automatic
    Thue-Morse sequence takes only the two values {0,1} however far we sample."""
    values = {thue_morse_via_dfao(n) for n in range(upto)}
    print(f"distinct values among n=0..{upto-1}: {sorted(values)}")
    assert values <= {0, 1}
    print("range is finite (subset of out-labels): OK")

if __name__ == "__main__":
    range_finite_demo()

from __future__ import annotations
from typing import List, Set

def mod7_reachset_and_occurrence(targets: List[int]) -> None:
    """Theorems 10 & 14 on the residue-mod-7 DFAO (step r,b -> (2r+b) mod 7).
    Computes reachSet by BFS (stabilising within |Q|=7 rounds) and decides which
    residues actually occur as outputs."""
    k, states, q0 = 2, tuple(range(7)), 0
    step = lambda r, b: (2 * r + b) % 7
    current: Set[int] = {q0}
    rounds = 0
    while True:
        nxt = set(current)
        for r in current:
            for b in range(k):
                nxt.add(step(r, b))
        if nxt == current:
            break
        current = nxt
        rounds += 1
    print(f"reachSet = {sorted(current)}, stabilised after {rounds} rounds "
          f"(<= |Q| = {len(states)})")
    for t in targets:
        print(f"  output {t} occurs? {t in current}")

if __name__ == "__main__":
    mod7_reachset_and_occurrence([0, 3, 6, 7, 99])

